def gen(rng):
    def serialize(vals, left, right):
        out = [str(vals[0])]
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            for c in (left[u], right[u]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def random_tree(n, lo, hi, maxdepth=4900, chain=0, zigzag=False):
        vals = [rng.randint(lo, hi)]
        left, right, depth = [-1], [-1], [0]
        free = []
        def add(parent, side):
            vals.append(rng.randint(lo, hi))
            left.append(-1); right.append(-1)
            depth.append(depth[parent] + 1)
            idx = len(vals) - 1
            if side == 0:
                left[parent] = idx
            else:
                right[parent] = idx
            return idx
        cur = 0
        for _ in range(min(chain, n - 1)):
            side = rng.randint(0, 1) if zigzag else 1
            nxt = add(cur, side)
            cur = nxt
        free = [(u, s) for u in range(len(vals)) for s in (0, 1) if (left[u] if s == 0 else right[u]) == -1]
        while len(vals) < n:
            k = rng.randrange(len(free))
            free[k], free[-1] = free[-1], free[k]
            u, s = free.pop()
            if depth[u] >= maxdepth:
                continue
            c = add(u, s)
            free.append((c, 0))
            free.append((c, 1))
            if not free:
                break
        return serialize(vals, left, right)

    tests = [
        '7', '1 2', '1 null 2', '1 2 3 4 5 6 7', '5 null 8 null 2 null 9',
        '1 2 null 3 4 null 5 6 null null 7 null 8 null 9 null 10',
        '3 3 3 3 3 3 3', '1 2 3 null 4 5', '10 -5 null null -7',
    ]
    for _ in range(80):
        n = rng.randint(1, 18)
        tests.append(random_tree(n, -9, 9, chain=rng.randint(0, n), zigzag=rng.random() < 0.5))
    tests.append(random_tree(100000, -10**9, 10**9))
    tests.append(random_tree(100000, -50, 50, chain=4800, zigzag=True))
    tests.append(random_tree(100000, -1000, 1000, chain=4900))
    tests.append(random_tree(100000, 0, 9, chain=2000, zigzag=True))
    tests.append(random_tree(4999, -10**9, 10**9, chain=4998))
